package com.nobodiiiii.createbiotech.content.biocomputing.computer.flow;
import static org.junit.jupiter.api.Assertions.*;
import static com.nobodiiiii.createbiotech.content.biocomputing.editor.NativeLibraryReadDocuments.*;
import com.nobodiiiii.createbiotech.content.biocomputing.computation.*;
import com.nobodiiiii.createbiotech.content.biocomputing.computer.*;
import com.nobodiiiii.createbiotech.content.biocomputing.editor.*;
import com.nobodiiiii.createbiotech.content.biocomputing.network.serial.*;
import java.util.*;
import org.junit.jupiter.api.Test;
class NativeLibraryFailureTest {
 static DataValue.RecordValue packet(){return record("kind","library_command","target",record("x",0,"y",0,"z",0),"request","fresh","operation","status","sequence",0,"data",null);}
 static DataValue.RecordValue reply(){return record("kind","library_reply","target",record("x",0,"y",0,"z",0),"request","fresh","code",null,"sequence",null,"value",null);}
 static boolean match(DataValue response){var original=NativeLibraryOwnersTest.document("c");var body=original.flow().orElseThrow();var definition=(FlowProgram.Procedure)body.program(original.archive()).steps().stream().filter(FlowProgram.Procedure.class::isInstance).findFirst().orElseThrow();var p=new FlowProgram(Map.of("context",CONTEXT),List.of(new FlowProgram.Invoke("call",definition.key(),new FlowCallBindings(Map.of("context","context"),Map.of("outcome","outcome"))),definition,new FlowProgram.EndProcedure("end"))).withAssembly();var r=new FlowRuntime(UUID.randomUUID(),UUID.randomUUID(),p,record("context",record("p",packet(),"r",response)),new ResourceLimits(256,65536,1));for(int i=0;r.checkpoint().status()!=FlowRuntime.Status.COMPLETE;i++){assertTrue(i<4000);r.advance(1);if(r.checkpoint().status()==FlowRuntime.Status.FAILED)throw new ComputationException(r.checkpoint().diagnostic().orElseThrow().code(),"matcher",r.checkpoint().diagnostic().orElseThrow().message());}return ((DataValue.BooleanValue)((DataValue.RecordValue)r.checkpoint().locals().field("outcome")).field("m")).value();}
 @Test void matcherGuardsAllSixFieldsAndAcceptsExplicitNullWithoutReinterpretingOrdinaryRecords(){assertTrue(match(reply()));assertFalse(match(record("ordinary","record")));for(String field:List.of("kind","target","request","code","sequence","value")){var m=new LinkedHashMap<>(reply().fields());m.remove(field);assertFalse(match(new DataValue.RecordValue(m)),field);}for(String field:List.of("kind","target","request")){var m=new LinkedHashMap<>(reply().fields());m.put(field,new DataValue.TextValue("unrelated-or-stale"));assertFalse(match(new DataValue.RecordValue(m)),field);}assertEquals(ComputationException.Code.TYPE_MISMATCH,assertThrows(ComputationException.class,()->match(new DataValue.IntegerValue(3))).code());}
 @Test void sendFailureReturnsOriginalSnapshotWithoutRetryOrEnteringMatcher(){for(boolean missing:List.of(false,true)){var l=NativeLibraryOwnersTest.limits("cleric",5);var serial=missing?null:NativeLibraryOwnersTest.device(l);var service=NativeLibraryOwnersTest.install(NativeLibraryOwnersTest.document("b"),l,serial);var caller=new ComputerBlockHost(()->{});caller.installFlow(new FlowProgram(Map.of("packet",PACKET),List.of(new FlowProgram.Write("request","x0","packet"),new FlowProgram.Read("reply","x0","outcome",OUTCOME))).withAssembly(),record("packet",packet()),l,true);caller.setPaused(false,l,true);service.setPaused(false,l,true);for(int i=0;caller.flowSnapshot().orElseThrow().state().status()!=FlowRuntime.Status.COMPLETE;i++){assertTrue(i<1500);var sample=Map.of("x0",NativeLibraryStartupTest.status(service,"x0",l,caller,"x0",l));caller.tick(l,true);service.tick(l,true,sample);caller.exchange("x0",l,true,service,"x0",l,true);assertTrue(service.loaded(),service.diagnostic().toString());assertFalse(service.flowSnapshot().orElseThrow().pinClaims().entries().stream().anyMatch(c->c.pin().equals("x1")));}var outcome=(DataValue.RecordValue)caller.flowSnapshot().orElseThrow().state().locals().field("outcome");assertEquals(new DataValue.BooleanValue(false),outcome.field("ok"));assertEquals(SerialResult.send(missing?"unavailable":"closed"),outcome.field("value"));if(serial!=null)assertEquals("idle",serial.status("s0").transmit());}}
}
